renderGroup=function(){return shell('グループ','settings',`<h2>${esc(state.group.name)}</h2><p class="row-sub" style="margin:12px 0">オーナー ${esc(oName(state.ownerId))}</p>${action('group-picker','グループを切り替える','','row')}${own()?`<form data-form="group2">${field('グループ名','name',state.group.name,'text','required maxlength="100"')}<button class="primary" type="submit">保存</button></form>`:''}`,'settings');};
