function authScreen(){document.body.classList.remove('wide');return `<div class="auth-screen"><h1>部活運営</h1>${segments([['login','ログイン'],['register','登録']],ctx.authTab,'auth-tab')}<form data-form="auth">${ctx.authTab==='register'?field('名前','name','','text','required autocomplete="name"'):''}${field('メール','email','','email','required autocomplete="email"')}${field('パスワード','password','','password',`required minlength="10" maxlength="256" autocomplete="${ctx.authTab==='register'?'new-password':'current-password'}"`)}<button class="primary full" type="submit">${ctx.authTab==='login'?'ログイン':'登録'}</button></form><div class="form-actions">${action('start-demo','デモを開く','','secondary full')}</div></div>`;}
