function mutationPermission(act){const groups={events:['cancel-event'],tasks:['delete-task'],notices:['delete-notice'],attendance:['attendance-toggle'],people:[],plans:['register-car','new-car','car-menu','delete-car','copy-open','copy-apply','split-apply','merge-apply','leg-enabled','need-toggle','assign-choice','charge-edit','statement-lock','statement-reopen'],equipment:['stock'],training:['practice-defaults','practice-save','practice-draft-save','practice-edit','practice-copy','practice-history-add','practice-history-delete','practice-history-edit-toggle','menu-delete','category-add','category-edit','category-delete','category-save','category-edit-toggle','menu-reorder-toggle','menu-move','training-import']};for(const [k,acts]of Object.entries(groups))if(acts.includes(act))return edit(k);if(['role-edit','invite2','operator-transfer','operator-remove'].includes(act))return own();return true;}
